// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Vite
// plugin that tells the Electron app where to look for the Vite-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_VITE_DEV_SERVER_URL: string;
declare const MAIN_WINDOW_VITE_NAME: string;

interface IDictionary<T> {
    [key: string]: T;
}

interface IBackend {
    type: string;
    name: string;
    command: string;
    argsPrefix: string[];
}

interface IImageTag {
    version: string;
}

interface IImage {
    name: string;
    tag: string;
}

interface IFileSystemNode {
    name: string;
    type: string;
    path: string;
    children?: IFileSystemNode[];
}

interface IFileSystemSample extends IFileSystemNode {
    type: "sample";
    folder: string;
    isPaired: boolean;
    isCompressed: boolean;
    metadata?: ISampleMetadata;
}

interface ISampleMetadata {
    spikeAmount?: number;
    totalWeight?: number;
    additional?: Map<string, string>;
}

interface IMergePairsArgs {
    fastq_maxdiffs: number;
    fastq_pctid: number;
    fastq_minmergelen: number;
    fastq_maxmergelen: number;
}

interface ITrimBothSidesArgs {
    stripleft: number;
    stripright: number;
}

interface ITrimOneSideArgs {
    stripleft: number;
}

interface IFilterBothSidesArgs {
    fastq_maxee_rate: number;
    fastq_truncqual: number;
}

interface IFilterOneSideArgs {
    fastq_maxee_rate: number;
    fastq_truncqual: number;
}

interface IIndividualSampleClusterZOTUsArgs {
    minsize: number;
}

interface IDeNovoClusterOTUsArgs {
    minsize: number;
    abund_limit: number;
    sample_wise_correction: boolean;
}

interface IFilter16SArgs {
    e: number;
    num_alignments: number;
}

interface IBuildZOTUTableArgs {
    match_id: number;
}

interface IAddTaxArgs {
    turn: string;
}

interface IClusterZOTUsArgs {
    minsize: number;
    abund_limit: number;
    sample_wise_correction: boolean;
    match_id: number;
}

interface IComplexTICArgs {
    family_sim: number;
    genus_sim: number;
    species_sim: number;
    abund_limit: number;
    sample_wise_correction: boolean;
}

interface ITACClusterArgs {
    abund_limit: number;
    sample_wise_correction: boolean;
    cluster_thr: number;
}

interface ITacticArguments {
    MergePairsArgs: IMergePairsArgs;
    TrimBothSidesArgs: ITrimBothSidesArgs;
    TrimOneSideArgs: ITrimOneSideArgs;
    FilterBothSidesArgs: IFilterBothSidesArgs;
    FilterOneSideArgs: IFilterOneSideArgs;
    IndividualSampleClusterZOTUsArgs: IIndividualSampleClusterZOTUsArgs;
    Filter16SArgs: IFilter16SArgs;
    BuildZOTUTableArgs: IBuildZOTUTableArgs;
    AddTaxArgs: IAddTaxArgs;
    ClusterZOTUsArgs: IClusterZOTUsArgs;
}

interface ITacticArgumentsTICMode extends ITacticArguments {
    ComplexTICArgs: IComplexTICArgs;
}

interface ITacticArgumentsDeNovoMode extends ITacticArguments {
    DeNovoClusterOTUsArgs: IDeNovoClusterOTUsArgs;
}

interface ITacticArgumentsTACMode extends ITacticArguments {
    TACClusterArgs: ITACClusterArgs;
}

interface ITacticBaseDirectory {
    path: string;
}

// modeled after https://docs.github.com/en/rest/releases/releases?apiVersion=2022-11-28#get-a-release-by-tag-name
interface GitHubAsset {
    "url": string;
    "browser_download_url": string;
    "id": number;
    "node_id": string;
    "name": string;
    "label": string;
    "state": string;
    "content_type": string;
    "size": number;
    "digest"?: string | null;  // e.g., "sha256:1d27…", computed by GitHub; null for files uploaded before mid-2025
    "download_count": number;
    "created_at": string;
    "updated_at": string;
    "uploader": object;
}

// modeled after https://docs.github.com/en/rest/releases/releases?apiVersion=2022-11-28#get-the-latest-release
interface GitHubRelease {
    "assets_url": string;
    "upload_url": string;
    "tarball_url": string;
    "zipball_url": string;
    "created_at": string;
    "published_at": string;
    "draft": boolean;
    "id": number;
    "node_id": string;
    "author": object;
    "html_url": string;
    "name": string;
    "prerelease": boolean;
    "tag_name": string;
    "target_commitish": string;
    "assets": GitHubAsset[];
    "url": string;
}

interface NumberRange {
    min: number | null;
    max: number | null;
}

interface SemanticVersionMatcher {
    major: number | NumberRange | null;
    minor: number | NumberRange | null;
    patch: number | NumberRange | null;
}

interface Progress {
    step: string;
    message: string;
    state: string;
    error?: {
        code: string;
        helpUrl: string;
    };
}

interface Repository {
    owner: string;
    repo: string;
}

interface IBind {
    source: string;
    target: string;
}

interface IRunOptions {
    binds?: IBind[];
}
